/// Fetches the CIK dynamically from SEC EDGAR if not found in static list
pub async fn resolve_cik(client: &reqwest::Client, ticker: &str) -> Result<Option<String>> {
    let t_upper = ticker.to_uppercase();
    if let Some(static_cik) = get_static_cik(&t_upper) {
        return Ok(Some(static_cik.to_string()));
    }

    let url = "https://www.sec.gov/files/company_tickers.json";
    let res = client
        .get(url)
        .header(reqwest::header::USER_AGENT, "Stonk/1.0 (admin@stonk.dev)")
        .send()
        .await?;

    if !res.status().is_success() {
        return Ok(None);
    }

    let json_data: serde_json::Value = res.json().await?;
    if let Some(obj) = json_data.as_object() {
        for v in obj.values() {
            let t_match = v["ticker"]
                .as_str()
                .map(|t| t.eq_ignore_ascii_case(&t_upper))
                .unwrap_or(false);
            let cik_opt = v["cik_str"].as_u64();
            if t_match && cik_opt.is_some() {
                return Ok(Some(format!("{:010}", cik_opt.unwrap())));
            }
        }
    }

    Ok(None)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_static_cik_lookups() {
        assert_eq!(get_static_cik("NVDA"), Some("0001045810"));
        assert_eq!(get_static_cik("META"), Some("0001326801"));
        assert_eq!(get_static_cik("AAPL"), Some("0000320193"));
        assert_eq!(get_static_cik("TSM"), Some("0001046179"));
        assert_eq!(get_static_cik("MU"), Some("0000723125"));
    }
}
